namespace cavpqc {
namespace {
void require(bool condition, const char* message) { if (!condition) throw std::runtime_error(message); }
template <typename T, void (*Free)(T*)> using Provider = std::unique_ptr<T, decltype(Free)>;
int nibble(char c) { if (c >= '0' && c <= '9') return c - '0'; if (c >= 'a' && c <= 'f') return c - 'a' + 10; if (c >= 'A' && c <= 'F') return c - 'A' + 10; return -1; }
std::mutex directoryMutex;
std::unordered_map<std::string, Bytes> directory;
}
KemKeyPair PqcCrypto::generateKemKeyPair() const { Provider<OQS_KEM, OQS_KEM_free> kem(OQS_KEM_new(OQS_KEM_alg_ml_kem_768), OQS_KEM_free); require(kem != nullptr, "ML-KEM-768 unavailable"); KemKeyPair result{Bytes(kem->length_public_key), Bytes(kem->length_secret_key)}; require(OQS_KEM_keypair(kem.get(), result.publicKey.data(), result.secretKey.data()) == OQS_SUCCESS, "ML-KEM keypair failed"); return result; }
SigKeyPair PqcCrypto::generateSigKeyPair() const { Provider<OQS_SIG, OQS_SIG_free> sig(OQS_SIG_new(OQS_SIG_alg_ml_dsa_65), OQS_SIG_free); require(sig != nullptr, "ML-DSA-65 unavailable"); SigKeyPair result{Bytes(sig->length_public_key), Bytes(sig->length_secret_key)}; require(OQS_SIG_keypair(sig.get(), result.publicKey.data(), result.secretKey.data()) == OQS_SUCCESS, "ML-DSA keypair failed"); return result; }
std::pair<Bytes, Bytes> PqcCrypto::encapsulate(const Bytes& pk) const { Provider<OQS_KEM, OQS_KEM_free> kem(OQS_KEM_new(OQS_KEM_alg_ml_kem_768), OQS_KEM_free); require(kem && pk.size() == kem->length_public_key, "invalid ML-KEM public key"); Bytes ct(kem->length_ciphertext), ss(kem->length_shared_secret); require(OQS_KEM_encaps(kem.get(), ct.data(), ss.data(), pk.data()) == OQS_SUCCESS, "ML-KEM encapsulation failed"); return {std::move(ct), std::move(ss)}; }
Bytes PqcCrypto::decapsulate(const Bytes& sk, const Bytes& ct) const { Provider<OQS_KEM, OQS_KEM_free> kem(OQS_KEM_new(OQS_KEM_alg_ml_kem_768), OQS_KEM_free); require(kem && sk.size() == kem->length_secret_key && ct.size() == kem->length_ciphertext, "invalid ML-KEM input"); Bytes ss(kem->length_shared_secret); require(OQS_KEM_decaps(kem.get(), ss.data(), ct.data(), sk.data()) == OQS_SUCCESS, "ML-KEM decapsulation failed"); return ss; }
Bytes PqcCrypto::sign(const Bytes& sk, const Bytes& message) const { Provider<OQS_SIG, OQS_SIG_free> sig(OQS_SIG_new(OQS_SIG_alg_ml_dsa_65), OQS_SIG_free); require(sig && sk.size() == sig->length_secret_key, "invalid ML-DSA secret key"); Bytes out(sig->length_signature); size_t length = 0; require(OQS_SIG_sign(sig.get(), out.data(), &length, message.data(), message.size(), sk.data()) == OQS_SUCCESS, "ML-DSA signing failed"); out.resize(length); return out; }
bool PqcCrypto::verify(const Bytes& pk, const Bytes& message, const Bytes& signature) const { Provider<OQS_SIG, OQS_SIG_free> sig(OQS_SIG_new(OQS_SIG_alg_ml_dsa_65), OQS_SIG_free); return sig && pk.size() == sig->length_public_key && OQS_SIG_verify(sig.get(), message.data(), message.size(), signature.data(), signature.size(), pk.data()) == OQS_SUCCESS; }
Bytes PqcCrypto::random(std::size_t length) const { Bytes out(length); OQS_randombytes(out.data(), out.size()); return out; }
Bytes PqcCrypto::shake256(const Bytes& input, std::size_t length) const { Bytes out(length); EVP_MD_CTX* ctx = EVP_MD_CTX_new(); require(ctx, "SHAKE context failed"); const bool ok = EVP_DigestInit_ex(ctx, EVP_shake256(), nullptr) == 1 && EVP_DigestUpdate(ctx, input.data(), input.size()) == 1 && EVP_DigestFinalXOF(ctx, out.data(), out.size()) == 1; EVP_MD_CTX_free(ctx); require(ok, "SHAKE-256 failed"); return out; }
Bytes PqcCrypto::hkdfSha384(const Bytes& ikm, const Bytes& salt, const std::string& info, std::size_t length) const { EVP_PKEY_CTX* ctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HKDF, nullptr); require(ctx, "HKDF context failed"); Bytes out(length); size_t outLength = length; const bool ok = EVP_PKEY_derive_init(ctx) > 0 && EVP_PKEY_CTX_set_hkdf_md(ctx, EVP_sha384()) > 0 && EVP_PKEY_CTX_set1_hkdf_salt(ctx, salt.data(), salt.size()) > 0 && EVP_PKEY_CTX_set1_hkdf_key(ctx, ikm.data(), ikm.size()) > 0 && EVP_PKEY_CTX_add1_hkdf_info(ctx, reinterpret_cast<const unsigned char*>(info.data()), info.size()) > 0 && EVP_PKEY_derive(ctx, out.data(), &outLength) > 0; EVP_PKEY_CTX_free(ctx); require(ok && outLength == length, "HKDF-SHA-384 failed"); return out; }
Bytes PqcCrypto::hmacSha384(const Bytes& key, const Bytes& input) const { Bytes out(EVP_MAX_MD_SIZE); unsigned int length = 0; require(HMAC(EVP_sha384(), key.data(), key.size(), input.data(), input.size(), out.data(), &length), "HMAC-SHA-384 failed"); out.resize(length); return out; }
AeadCiphertext PqcCrypto::aeadEncrypt(const Bytes& key, const Bytes& plaintext, const Bytes& associatedData) const { require(key.size() == 32, "AES-256-GCM requires a 32-byte key"); AeadCiphertext out{random(12), Bytes(plaintext.size()), Bytes(16)}; EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new(); require(ctx, "AES-GCM context failed"); int length = 0; int ciphertextLength = 0; const bool ok = EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, nullptr, nullptr) == 1 && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, static_cast<int>(out.nonce.size()), nullptr) == 1 && EVP_EncryptInit_ex(ctx, nullptr, nullptr, key.data(), out.nonce.data()) == 1 && EVP_EncryptUpdate(ctx, nullptr, &length, associatedData.data(), static_cast<int>(associatedData.size())) == 1 && EVP_EncryptUpdate(ctx, out.ciphertext.data(), &length, plaintext.data(), static_cast<int>(plaintext.size())) == 1; ciphertextLength = length; const bool finalized = EVP_EncryptFinal_ex(ctx, out.ciphertext.data() + ciphertextLength, &length) == 1 && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, static_cast<int>(out.tag.size()), out.tag.data()) == 1; EVP_CIPHER_CTX_free(ctx); require(ok && finalized, "AES-256-GCM encryption failed"); out.ciphertext.resize(ciphertextLength + length); return out; }
Bytes PqcCrypto::aeadDecrypt(const Bytes& key, const AeadCiphertext& encrypted, const Bytes& associatedData) const { require(key.size() == 32 && encrypted.nonce.size() == 12 && encrypted.tag.size() == 16, "invalid AES-256-GCM input"); Bytes plaintext(encrypted.ciphertext.size()); EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new(); require(ctx, "AES-GCM context failed"); int length = 0; int plaintextLength = 0; const bool ok = EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, nullptr, nullptr) == 1 && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, static_cast<int>(encrypted.nonce.size()), nullptr) == 1 && EVP_DecryptInit_ex(ctx, nullptr, nullptr, key.data(), encrypted.nonce.data()) == 1 && EVP_DecryptUpdate(ctx, nullptr, &length, associatedData.data(), static_cast<int>(associatedData.size())) == 1 && EVP_DecryptUpdate(ctx, plaintext.data(), &length, encrypted.ciphertext.data(), static_cast<int>(encrypted.ciphertext.size())) == 1; plaintextLength = length; const bool finalized = EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, static_cast<int>(encrypted.tag.size()), const_cast<std::uint8_t*>(encrypted.tag.data())) == 1 && EVP_DecryptFinal_ex(ctx, plaintext.data() + plaintextLength, &length) == 1; EVP_CIPHER_CTX_free(ctx); require(ok && finalized, "AES-256-GCM authentication failed"); plaintext.resize(plaintextLength + length); return plaintext; }
std::string PqcCrypto::hex(const Bytes& input) { static constexpr char digits[] = "0123456789abcdef"; std::string result; result.reserve(input.size() * 2); for (auto byte : input) { result += digits[byte >> 4]; result += digits[byte & 15]; } return result; }
Bytes PqcCrypto::unhex(const std::string& input) { require(input.size() % 2 == 0, "invalid hex length"); Bytes result; result.reserve(input.size() / 2); for (std::size_t i = 0; i < input.size(); i += 2) { const int high = nibble(input[i]), low = nibble(input[i + 1]); require(high >= 0 && low >= 0, "invalid hex character"); result.push_back(static_cast<std::uint8_t>((high << 4) | low)); } return result; }
void SimulationCredentialDirectory::registerSigningKey(const std::string& subject, const Bytes& publicKey) { std::lock_guard<std::mutex> lock(directoryMutex); directory[subject] = publicKey; }
Bytes SimulationCredentialDirectory::signingKey(const std::string& subject) { std::lock_guard<std::mutex> lock(directoryMutex); const auto found = directory.find(subject); if (found == directory.end()) throw std::runtime_error("simulation credential missing: " + subject); return found->second; }
}
